    # other members
    for orig_name in dir(subject):
        try:
            value = attrgetter(subject, orig_name)
            directly_defined = orig_name in obj_dict
            name = unmangle(subject, orig_name)
            if name and name not in members:
                # unwrap classmethod-wrapped properties (Python 3.9+)
                if directly_defined:
                    raw = obj_dict.get(orig_name)
                    try:
                        if isinstance(raw, classmethod) and isinstance(raw.__func__, property):
                            value = raw.__func__
                    except Exception:
                        pass
                members[name] = Attribute(name, directly_defined, value)
        except AttributeError:
            continue

